## 2. 设备树

### `dts/tuya_t5_e1_ipex.dts`

```dts
/*
 * Copyright (c) 2026 BK7258 Zephyr Port Contributors
 * SPDX-License-Identifier: Apache-2.0
 */

/dts-v1/;
#include <arm/armv8-m.dtsi>
#include <tuya_t5_e1_ipex-pinctrl.dtsi>

/ {
    model = "Tuya T5-E1-IPEX Module";
    compatible = "tuya,t5-e1-ipex";

    chosen {
        zephyr,console = &uart1;
        zephyr,shell-uart = &uart1;
        zephyr,uart-mcumgr = &uart1;
        zephyr,bt-mon-uart = &uart1;
        zephyr,bt-c2h-uart = &uart1;
    };

    cpus {
        #address-cells = <1>;
        #size-cells = <0>;

        cpu@0 {
            compatible = "arm,cortex-m33";
            reg = <0>;
        };

        /* 从核暂时不支持 */
    };

    /* 时钟树 */
    clk_26m: clock-26m {
        compatible = "fixed-clock";
        clock-frequency = <26000000>;
    };

    sysclk: clock-system {
        compatible = "fixed-clock";
        clock-frequency = <120000000>;
    };

    /* Flash分区 */
    soc {
        flash0: flash@0 {
            compatible = "soc-nv-flash";
            reg = <0x0 0x400000>;
            erase-block-size = <4096>;
            write-block-size = <4>;

            partitions {
                compatible = "fixed-partitions";
                #address-cells = <1>;
                #size-cells = <1>;

                partition_0: partition@0 {
                    label = "bootloader";
                    reg = <0x00000000 0x20000>;
                    read-only;
                };

                partition_1: partition@20000 {
                    label = "mcuboot";
                    reg = <0x00020000 0x20000>;
                };

                partition_2: partition@40000 {
                    label = "firmware";
                    reg = <0x00040000 0x3c0000>;
                };
            };
        };
    };
};

&uart1 {
    status = "okay";
    current-speed = <460800>;
    pinctrl-0 = &uart1_default;
    pinctrl-names = "default";
};

/* 外设节点待添加 */
```

